scene.addModifier:
addModifier(modifier: Modifier, ignoreUpdate?: boolean, playSound?: boolean, virtual?: boolean, instant?: boolean): Promise<void> {
		return new Promise(resolve => {
			const soundName = modifier.type.soundName;
			this.validateAchvs(ModifierAchv, modifier);
			const modifiersToRemove: PersistentModifier[] = [];
			if (modifier instanceof PersistentModifier) {
				if (modifier instanceof TerastallizeModifier)
					modifiersToRemove.push(...(this.findModifiers(m => m instanceof TerastallizeModifier && m.pokemonId === modifier.pokemonId)));
				if ((modifier as PersistentModifier).add(this.modifiers, !!virtual, this)) {
					if (modifier instanceof PokemonFormChangeItemModifier || modifier instanceof TerastallizeModifier)
						modifier.apply([ this.getPokemonById(modifier.pokemonId), true ]);
					if (playSound && !this.sound.get(soundName))
						this.playSound(soundName);
				} else if (!virtual) {
					const defaultModifierType = getDefaultModifierTypeForTier(modifier.type.tier);
					this.queueMessage(`The stack for this item is full.\n You will receive ${defaultModifierType.name} instead.`, null, true);
					return this.addModifier(defaultModifierType.newModifier(), ignoreUpdate, playSound, false, instant).then(() => resolve());
				}

				for (let rm of modifiersToRemove)
					this.removeModifier(rm);

				if (!ignoreUpdate && !virtual)
					return this.updateModifiers(true, instant).then(() => resolve());
			} else if (modifier instanceof ConsumableModifier) {
				if (playSound && !this.sound.get(soundName))
					this.playSound(soundName);

				if (modifier instanceof ConsumablePokemonModifier) {
					for (let p in this.party) {
						const pokemon = this.party[p];

						const args: any[] = [ pokemon ];
						if (modifier instanceof PokemonHpRestoreModifier) {
							if (!(modifier as PokemonHpRestoreModifier).fainted) {
								const hpRestoreMultiplier = new Utils.IntegerHolder(1);
								this.applyModifiers(HealingBoosterModifier, true, hpRestoreMultiplier);
								args.push(hpRestoreMultiplier.value);
							} else
								args.push(1);
						} else if (modifier instanceof FusePokemonModifier)
							args.push(this.getPokemonById(modifier.fusePokemonId) as PlayerPokemon);

						if (modifier.shouldApply(args))
							modifier.apply(args);
					}

					return Promise.allSettled(this.party.map(p => p.updateInfo(instant))).then(() => resolve());
				} else {
					const args = [ this ];
					if (modifier.shouldApply(args))
						modifier.apply(args);
				}
			}

			resolve();
		});
	}

scene.addEnemyModifier:
addEnemyModifier(modifier: PersistentModifier, ignoreUpdate?: boolean, instant?: boolean): Promise<void> {
		return new Promise(resolve => {
			const modifiersToRemove: PersistentModifier[] = [];
			if (modifier instanceof TerastallizeModifier)
					modifiersToRemove.push(...(this.findModifiers(m => m instanceof TerastallizeModifier && m.pokemonId === modifier.pokemonId, false)));
			if ((modifier as PersistentModifier).add(this.enemyModifiers, false, this)) {
				if (modifier instanceof PokemonFormChangeItemModifier || modifier instanceof TerastallizeModifier)
					modifier.apply([ this.getPokemonById(modifier.pokemonId), true ]);
				for (let rm of modifiersToRemove)
					this.removeModifier(rm, true);
			}
			if (!ignoreUpdate)
				this.updateModifiers(false, instant).then(() => resolve());
			else
				resolve();
		});
	}

scene.tryTransferHeldItemModifier:
tryTransferHeldItemModifier(itemModifier: PokemonHeldItemModifier, target: Pokemon, transferStack: boolean, playSound: boolean, instant?: boolean, ignoreUpdate?: boolean): Promise<boolean> {
		return new Promise(resolve => {
			const source = itemModifier.pokemonId ? itemModifier.getPokemon(target.scene) : null;
			const cancelled = new Utils.BooleanHolder(false);
			Utils.executeIf(source && source.isPlayer() !== target.isPlayer(), () => applyAbAttrs(BlockItemTheftAbAttr, source, cancelled)).then(() => {
				if (cancelled.value)
					return resolve(false);
				const newItemModifier = itemModifier.clone() as PokemonHeldItemModifier;
				newItemModifier.pokemonId = target.id;
				const matchingModifier = target.scene.findModifier(m => m instanceof PokemonHeldItemModifier
					&& (m as PokemonHeldItemModifier).matchType(itemModifier) && m.pokemonId === target.id, target.isPlayer()) as PokemonHeldItemModifier;
				let removeOld = true;
				if (matchingModifier) {
					const maxStackCount = matchingModifier.getMaxStackCount(target.scene);
					if (matchingModifier.stackCount >= maxStackCount)
						return resolve(false);
					const countTaken = transferStack ? Math.min(itemModifier.stackCount, maxStackCount - matchingModifier.stackCount) : 1;
					itemModifier.stackCount -= countTaken;
					newItemModifier.stackCount = matchingModifier.stackCount + countTaken;
					removeOld = !itemModifier.stackCount;
				} else if (!transferStack) {
					newItemModifier.stackCount = 1;
					removeOld = !(--itemModifier.stackCount);
				}
				if (!removeOld || !source || this.removeModifier(itemModifier, !source.isPlayer())) {
					const addModifier = () => {
						if (!matchingModifier || this.removeModifier(matchingModifier, !target.isPlayer())) {
							if (target.isPlayer())
								this.addModifier(newItemModifier, ignoreUpdate, playSound, false, instant).then(() => resolve(true));
							else
								this.addEnemyModifier(newItemModifier, ignoreUpdate, instant).then(() => resolve(true));
						} else
							resolve(false);
					};
					if (source && source.isPlayer() !== target.isPlayer() && !ignoreUpdate)
						this.updateModifiers(source.isPlayer(), instant).then(() => addModifier());
					else
						addModifier();
					return;
				}
				resolve(false);
			});
		});
	}

transferApply:
apply(args: any[]): boolean {
    const pokemon = args[0] as Pokemon;
    const opponents = pokemon.getOpponents();

    if (!opponents.length)
      return false;

    const targetPokemon = opponents[pokemon.randSeedInt(opponents.length)];

    const transferredItemCount = this.getTransferredItemCount();
    if (!transferredItemCount)
      return false;

    const withinParty = pokemon.isPlayer() === targetPokemon.isPlayer();

    const transferredModifierTypes: ModifierTypes.ModifierType[] = [];
    const itemModifiers = pokemon.scene.findModifiers(m => m instanceof PokemonHeldItemModifier
        && (m as PokemonHeldItemModifier).pokemonId === targetPokemon.id && m.getTransferrable(withinParty), targetPokemon.isPlayer()) as PokemonHeldItemModifier[];
    let highestItemTier = itemModifiers.map(m => m.type.getOrInferTier()).reduce((highestTier, tier) => Math.max(tier, highestTier), 0);
    let tierItemModifiers = itemModifiers.filter(m => m.type.getOrInferTier() === highestItemTier);

    let heldItemTransferPromises: Promise<void>[] = [];

    for (let i = 0; i < transferredItemCount; i++) {
      if (!tierItemModifiers.length) {
        while (highestItemTier-- && !tierItemModifiers.length)
          tierItemModifiers = itemModifiers.filter(m => m.type.tier === highestItemTier);
        if (!tierItemModifiers.length)
          break;
      }
      const randItemIndex = pokemon.randSeedInt(itemModifiers.length);
      const randItem = itemModifiers[randItemIndex];
      heldItemTransferPromises.push(pokemon.scene.tryTransferHeldItemModifier(randItem, pokemon, false, false, true).then(success => {
        if (success) {
          transferredModifierTypes.push(randItem.type);
          itemModifiers.splice(randItemIndex, 1);
        }
      }));
    }

    Promise.all(heldItemTransferPromises).then(() => {
      for (let mt of transferredModifierTypes)
        pokemon.scene.queueMessage(this.getTransferMessage(pokemon, targetPokemon, mt));
    });

    return !!transferredModifierTypes.length;
  }
